from rules import SOLVERS

def solve(data):
    return {component_id: solver(data[component_id])
            for component_id, solver in SOLVERS.items()}

def _ledger(data, priority, tax_base, rounding):
    cutoff = data.get("cutoff", 10**9)
    chosen = {}
    for pos, event in enumerate(data["events"]):
        seq = event.get("sequence", 0)
        if seq > cutoff:
            continue
        eid = event.get("id", "anonymous:" + str(pos))
        key = ((seq, event.get("revision", 0), pos) if priority == "sequence"
               else (event.get("revision", 0), pos))
        if eid not in chosen or key > chosen[eid][0]:
            chosen[eid] = (key, event)

    balances = dict(data.get("opening", {}))
    def rounded(n, mode):
        return (n + 5000) // 10000 if mode == "half_up" else n // 10000

    for _, event in chosen.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount), data["rounding"])
        base = raw if tax_base == "original" else net
        total = net + rounded(base * event.get("tax_bp", 0), data["rounding"])
        if event.get("kind") == "refund":
            total = -total
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def _build_ledger(priority, tax_base):
    return lambda data: _ledger(data, priority, tax_base, data["rounding"])


def _build_component_06():
    from itertools import product

    def solve(data):
        packages = data["packages"]
        names = sorted(packages, reverse=True)
        features = set(data.get("features", []))
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        domains = []
        for name in names:
            rows = [r for r in packages[name]
                    if r["version"] not in blocked.get(name, [])
                    and (name not in pins or r["version"] == pins[name])]
            domains.append([None] + rows)

        best = None
        for choice in product(*domains):
            selected = {name: row for name, row in zip(names, choice) if row is not None}
            if any(name not in selected or not lo <= selected[name]["version"] <= hi
                   for name, (lo, hi) in data["roots"].items()):
                continue
            edges = {name: [] for name in selected}
            ok = True
            for name, row in selected.items():
                for dep in row.get("deps", []):
                    feature = dep.get("feature", "")
                    if feature and feature not in features:
                        continue
                    other = dep["name"]
                    if other not in selected or not dep["min"] <= selected[other]["version"] <= dep["max"]:
                        ok = False
                        break
                    edges[name].append(other)
                if not ok:
                    break
            if not ok:
                continue
            # Every installed package must be in the active closure of the roots.
            reachable = set()
            stack = list(data["roots"])
            while stack:
                name = stack.pop()
                if name in reachable or name not in selected:
                    continue
                reachable.add(name)
                stack.extend(edges[name])
            if reachable != set(selected):
                continue
            visiting, visited = set(), set()
            def visit(name):
                if name in visiting:
                    return False
                if name in visited:
                    return True
                visiting.add(name)
                if any(not visit(child) for child in edges[name]):
                    return False
                visiting.remove(name)
                visited.add(name)
                return True
            if not all(visit(name) for name in selected):
                continue
            vector = tuple(selected[n]["version"] if n in selected else -1 for n in names)
            if best is None or vector < best[0]:
                best = (vector, {n: selected[n]["version"] for n in names if n in selected})
        return {"versions": best[1]} if best else {"error": "unsatisfiable"}
    return solve


def _build_component_07():
    from itertools import combinations

    def solve(data):
        jobs = data["jobs"]
        k = data["k"]
        blocked = set(data.get("blocked", []))
        mandatory = set(data.get("mandatory", []))
        quotas = data.get("quotas", {})
        eligible = [j for j in jobs if j["id"] not in blocked]
        best_value, best_ids = None, None
        for chosen in combinations(eligible, k):
            ids = {j["id"] for j in chosen}
            if not mandatory <= ids:
                continue
            counts = {}
            for job in chosen:
                counts[job["group"]] = counts.get(job["group"], 0) + 1
            if any(not lo <= counts.get(group, 0) <= hi
                   for group, (lo, hi) in quotas.items()):
                continue
            ordered = sorted(chosen, key=lambda j: (j["start"], j["end"]))
            if any(ordered[i]["end"] > ordered[i + 1]["start"]
                   for i in range(len(ordered) - 1)):
                continue
            value = sum(j["value"] for j in chosen)
            id_list = tuple(sorted(ids))
            if (best_value is None or value > best_value or
                    (value == best_value and id_list > best_ids)):
                best_value, best_ids = value, id_list
        if best_value is None:
            return {"error": "impossible"}
        return {"selected": list(best_ids), "value": best_value}
    return solve


def _build_component_08():
    import heapq

    def solve(data):
        required = data.get("required", [])
        bit = {node: 1 << i for i, node in enumerate(required)}
        full = (1 << len(required)) - 1
        graph = [[] for _ in range(data["n"])]
        for edge in data["edges"]:
            graph[edge["u"]].append(edge)
        source = data["source"]
        initial_mask = bit.get(source, 0)
        start_state = (source, initial_mask, data["coupons"])
        start = data["start"]
        distances = {start_state: start}
        queue = [(start, source, initial_mask, data["coupons"])]
        while queue:
            time, node, mask, remaining = heapq.heappop(queue)
            state = (node, mask, remaining)
            if distances.get(state) != time:
                continue
            if node == data["target"] and mask == full and remaining == 0:
                return {"arrival": time}
            for edge in graph[node]:
                depart = max(time, edge["open"])
                if depart >= edge["close"]:
                    continue
                options = [(edge["duration"], remaining)]
                if remaining:
                    duration = max(1, edge["duration"] - edge.get("discount", 0))
                    options.append((duration, remaining - 1))
                for duration, left in options:
                    arrival = depart + duration
                    if arrival > data["deadline"]:
                        continue
                    dest = edge["v"]
                    next_mask = mask | bit.get(dest, 0)
                    next_state = (dest, next_mask, left)
                    if arrival < distances.get(next_state, float("inf")):
                        distances[next_state] = arrival
                        heapq.heappush(queue, (arrival, dest, next_mask, left))
        return {"arrival": None}
    return solve


SOLVERS = {
    "component_01": _build_ledger("sequence", "original"),
    "component_02": _build_ledger("revision", "discounted"),
    "component_03": _build_ledger("sequence", "discounted"),
    "component_04": _build_ledger("revision", "original"),
    "component_05": _build_ledger("sequence", "original"),
    "component_06": _build_component_06(),
    "component_07": _build_component_07(),
    "component_08": _build_component_08(),
}
